        "welcomeBody": "DeepSeek Harness 0.2 vẫn đang ở giai đoạn xem trước và nhiều phần cần tiếp tục được cải thiện, hoàn thiện. Chúng tôi hoan nghênh phản hồi và góp ý từ tất cả nhà phát triển và người dùng. Ứng dụng desktop mới hiện hướng tới nhiều đối tượng người dùng, còn các tính năng nâng cao dành cho nhà phát triển có thể được bật trong phần cài đặt. Các tính năng sản phẩm và API plugin của DeepSeek Harness dự kiến sẽ tiếp tục thay đổi nhanh và phát triển, dần ổn định theo thời gian.\n\nChúng tôi mong được cùng người dùng và nhà phát triển trên khắp thế giới khám phá giới hạn của trí tuệ, dựa trên hạ tầng mã nguồn mở, có thể tái sử dụng và kết hợp. Chúng tôi mời mọi người hiện thực hóa ý tưởng của mình với DeepSeek Harness và tham gia cộng đồng để làm phong phú hệ sinh thái plugin.",
