      "Keep linked GitHub pull requests beside your conversation: follow checks and reviews, inspect diffs, and send feedback to the agent. Review local changes and use a separate worktree to isolate each task. GitHub features require the gh CLI installed and signed in on the host.": "Theo dõi các pull request GitHub liên kết bên cạnh cuộc hội thoại của bạn: theo dõi kiểm tra và đánh giá, xem diff và gửi phản hồi cho agent. Xem lại thay đổi cục bộ và dùng một worktree riêng để cô lập từng tác vụ. Các tính năng GitHub yêu cầu gh CLI đã cài đặt và đăng nhập trên máy chủ.",
